function add(type){mutate(()=>{const id=crypto.randomUUID();flow.nodes.push({id,type,title:type==='question'?'New question':type==='shape'?'New shape':'New deal type',x:(220-pan.x)/zoom,y:(160-pan.y)/zoom,answers:type==='question'?[{label:'Yes',target:''},{label:'No',target:''}]:[]});if(activeGroupId)flow.groups.find(g=>g.id===activeGroupId).members.push(id);if(!flow.start&&type!=='shape')flow.start=id;selected=new Set([id]);});}
