function groupBounds(g){const ns=flow.nodes.filter(n=>g.members.includes(n.id));if(!ns.length)return null;return {x:Math.min(...ns.map(n=>n.x))-22,y:Math.min(...ns.map(n=>n.y))-22,right:Math.max(...ns.map(n=>n.x+nodeWidth(n)))+22,bottom:Math.max(...ns.map(n=>n.y+height(n)))+22};}
