function groupTitleEditor(el){if(selectedGroups.size!==1)return;const group=flow.groups.find(g=>selectedGroups.has(g.id));if(!group)return;const wrap=document.createElement('div');wrap.innerHTML=`${group.stage?`<h3>Stage configuration</h3><pre class="source-json">${esc(JSON.stringify(group.stage,null,2))}</pre>`:''}<label>Group title</label><input id="group-title" value="${esc(group.title)}">`;el.append(wrap);$('#group-title').onchange=e=>mutate(()=>group.title=e.target.value);}

function sourceIdForLink(){const [type,a]=selectedLink.split(':');return type==='r'?linkObject().source:flow.nodes[+a].id;}
function drawBends(){const link=linkObject();if(!link?.points)return;link.points.forEach((point,i)=>{const handle=document.createElement('div');handle.className='bend-handle';handle.dataset.bend=i;handle.style.left=(point.x-6)+'px';handle.style.top=(point.y-6)+'px';$('.world').append(handle);});}
function formatEditor(n,el){const wrap=document.createElement('div');wrap.className='section';wrap.innerHTML=`<h2>Card formatting</h2><label>Shape</label><select id="card-shape">${['rounded','rectangle','diamond','ellipse','note'].map(v=>`<option value="${v}" ${(n.shape||'rounded')===v?'selected':''}>${v}</option>`).join('')}</select><label>Width / height</label><div class="row"><input id="card-width" type="number" min="160" max="1200" value="${nodeWidth(n)}" aria-label="Card width"><input id="card-height" type="number" min="78" max="1600" value="${height(n)}" aria-label="Card height"></div><label>Rotation (degrees)</label><input id="card-rotation" type="number" value="${n.rotation||0}"><label>Font size</label><input id="card-font" type="number" min="10" max="40" value="${n.fontSize||14}"><div class="row"><button id="card-bold">Bold</button><button id="card-italic">Italic</button></div><label>Fill color</label><input id="card-fill-color" type="color" value="${n.fill||'#ffffff'}"><label>Text color</label><input id="card-text-color" type="color" value="${n.textColor||'#243047'}"><label>Border color</label><input id="card-border-color" type="color" value="${n.borderColor||'#dce2e9'}">`;el.append(wrap);for(const [id,key,min,max] of [['card-width','width',160,1200],['card-height','height',78,1600],['card-rotation','rotation',-360,360],['card-font','fontSize',10,40]])$('#'+id).onchange=e=>mutate(()=>n[key]=Math.max(min,Math.min(max,+e.target.value||min)));$('#card-shape').onchange=e=>mutate(()=>n.shape=e.target.value);for(const [id,key] of [['card-fill-color','fill'],['card-text-color','textColor'],['card-border-color','borderColor']])$('#'+id).onchange=e=>{const value=e.target.value;mutate(()=>flow.nodes.filter(card=>selected.has(card.id)).forEach(card=>card[key]=value));};$('#card-bold').onclick=()=>mutate(()=>n.bold=!n.bold);$('#card-italic').onclick=()=>mutate(()=>n.italic=!n.italic);}
async function teamProject(){
 modal('<h3>Shared team project</h3><p>Changes save automatically. Other editors’ changes appear live. Independent edits merge automatically; overlapping edits stay local until resolved.</p><p id="team-info">Checking shared storage…</p><button id="team-load" disabled>Load latest team version</button> <button id="team-save" disabled>Save now</button> <button id="team-resolve" hidden>Resolve conflicting fields</button> <button id="team-replace" hidden>Replace team with my local version</button><div class="row"><button id="team-download" disabled>Download team JSON</button><button id="team-recovery">Download local recovery copy</button><button id="team-draft">Download pre-sync local draft</button></div>');
 $('#team-draft').disabled=!localStorage.getItem('question-tree-local-draft');$('#team-draft').onclick=()=>download(localStorage.getItem('question-tree-local-draft'),'question-tree-pre-sync-draft.json','application/json');$('#team-recovery').onclick=()=>{const recovery=localStorage.getItem('question-tree-cloud-backup')||localStorage.getItem('question-tree-backup');if(recovery)download(recovery,'question-tree-local-recovery.json','application/json');else toast('No recovery copy yet. Use JSON to export your current project.');};
 let remote;try{remote=await autoSync.read();}catch(error){$('#team-info').textContent=error.message;return;}if(!$('#team-info'))return;
 $('#team-info').textContent=remote.flow?'Team version '+remote.revision+' · '+remote.savedAt+' · '+remote.flow.nodes.length+' cards. Your local version has '+flow.nodes.length+' cards.':'No shared project yet.';
 $('#team-download').disabled=!remote.flow;$('#team-download').onclick=()=>download(JSON.stringify(remote.flow,null,2),'question-tree-team.json','application/json');$('#team-load').disabled=!remote.flow;
 $('#team-load').onclick=async()=>{$('.modal-backdrop')?.remove();await autoSync.refresh(false,true);};
 const conflict=autoSync.blocked||(cloudRevision!==null&&cloudRevision!==remote.revision);$('#team-save').disabled=conflict;$('#team-replace').hidden=!conflict;$('#team-resolve').hidden=!autoSync.conflicts.length;$('#team-resolve').onclick=reviewSyncConflicts;
 $('#team-save').onclick=async()=>{if(!autoSync.ready)await autoSync.refresh();await autoSync.flush();if($('#team-info'))$('#team-info').textContent=autoSync.code==='synced'?'Saved team version '+autoSync.revision:'Local work retained. '+autoSync.code;};
 $('#team-replace').onclick=async()=>{if(!backupFlow())return;await autoSync.replaceAfterReview(remote.revision);if($('#team-info'))$('#team-info').textContent=autoSync.code==='synced'?'Saved your version as team version '+autoSync.revision:'Another change or connection problem prevented replacement. Your local work is retained.';};
}

function outgoingConnections(n,el){const links=(flow.referenceLinks||[]).map((link,i)=>({link,i})).filter(({link})=>link.source===n.id);if(!links.length)return;const block=document.createElement('div');block.className='section';block.innerHTML=`<h2>JSON / custom connections</h2>${links.map(({link,i})=>`<button class="outgoing-link" data-edit-link="${i}" ${!allowedLink(flow,activeGroupId,n.id,link.target)?'disabled':''}>${esc(link.displayLabel||link.visibilityLabel||link.label||'Next')} → ${esc(link.target)}<small>${link.sourceWarning?'Source conflict':link.inferred?'Inferred relationship':link.visibilityDependencies?'JSON visibility dependency':link.confirmedAnswer?'User-confirmed':link.provenance==='json-order'?'JSON stage order':link.sourceRule?'JSON visibility rule':'Custom connection'}</small></button>`).join('')}`;el.append(block);block.querySelectorAll('[data-edit-link]').forEach(button=>button.onclick=()=>{const l=flow.referenceLinks[+button.dataset.editLink];if(!allowedLink(flow,activeGroupId,l.source,l.target))return;selectedLink='r:'+button.dataset.editLink;render();});}

function loadCloudRevision(){const value=localStorage.getItem('question-tree-team-revision');return value!==null&&/^\d+$/.test(value)?Number(value):null;}

function reviewSource(){return flow.sourceImport==='manual'&&flow.sourcePackage?convertPackage(flow.sourcePackage,sourceBaseline):suppliedFlow;}
function reviewQuestionData(){const uploaded=reviewSource(),upgrade=upgradeSource(flow,uploaded,sourceBaseline);const preserved=flow.sourceUpgrade?.preservedFields||upgrade.preserved;modal(`<h3>Uploaded question data</h3><p>153 question records recreated from questionnaire-v3.json and requested updates. 45 questions use number, currency, percentage, year, date or text inputs. 42 visibility rules are captured, including the property management branches.</p><p>Layout, groups, custom wording and edited routes are preserved. Screenshot routes and settings are excluded. Visibility rules are shown exactly as exported, without inferred question-to-field mappings.</p><h3>JSON source notes</h3><ul>${(uploaded.sourceConflicts||[]).map(c=>`<li>${esc(c.message)}</li>`).join('')}</ul><h3>Preserved custom fields (${preserved.length})</h3><p>${esc(preserved.join(', ')||'None detected')}</p><button id="apply-all-data" ${upgrade.changed?'':'disabled'} class="primary">Update unchanged source data</button><button id="rebuild-json">Recreate canvas from JSON only</button><button id="download-source">Download original JSON package</button><p>Edited cards can receive the source wording using Review uploaded source details in Properties.</p>`);$('#apply-all-data').onclick=()=>{if(!backupFlow())return;checkpoint();flow=upgrade.flow;clearSelection();$('.modal-backdrop').remove();render();toast('Question data updated; custom work preserved');};$('#rebuild-json').onclick=()=>{if(!backupFlow())return;checkpoint();flow=structuredClone(uploaded);if(!autoSync?.ready)cloudRevision=null;clearSelection();$('.title').value=flow.title;$('.modal-backdrop').remove();render();fit();toast('Recreated from JSON. Previous work is available in Backup.');};$('#download-source').onclick=()=>download(JSON.stringify(uploaded.sourcePackage,null,2),'questionnaire-v3.json','application/json');}

function enterGroup(id){lastGroupClick=null;const g=flow.groups.find(g=>g.id===id);if(!g)return;activeGroupId=id;clearSelection();connectFrom=null;tool='select';render();$('.canvas').focus({preventScroll:true});}
function exitGroup(){lastGroupClick=null;if(!activeGroupId)return;const id=activeGroupId;activeGroupId=null;clearSelection();const g=flow.groups.find(g=>g.id===id);if(g){selectedGroups.add(id);selected=new Set(g.members);}connectFrom=null;tool='select';render();$('.canvas').focus({preventScroll:true});}
function openGroup(e){if(tool!=='select'||spaceHeld)return;const target=e.target.closest('.node,[data-group]')?e.target:document.elementFromPoint(e.clientX,e.clientY);const card=target?.closest('.node'),id=target?.closest('[data-group]')?.dataset.group||ownerGroup(flow,card?.dataset.id)?.id;if(!id)return;if(activeGroupId){if(id===activeGroupId&&card){selected=new Set([card.dataset.id]);render();$('#node-title')?.focus();}return;}enterGroup(id);}
function linkInScope(key){const [type,a,b]=key.split(':'),link=type==='r'?flow.referenceLinks[+a]:flow.nodes[+a]?.answers[+b],source=type==='r'?link?.source:flow.nodes[+a]?.id;return link&&allowedLink(flow,activeGroupId,source,link.target);}
function updateIsolation(){const g=flow.groups.find(g=>g.id===activeGroupId);$('.canvas').classList.toggle('isolated',!!g);$('.group-edit-bar').hidden=!g;$('#group-edit-name').textContent=g?'Editing group: '+g.title:'';for(const el of $('.world').querySelectorAll('.node'))el.classList.toggle('outside-scope',!!g&&!g.members.includes(el.dataset.id));for(const el of $('.world').querySelectorAll('.group')){el.classList.toggle('editing-group',!!g&&el.dataset.group===g.id);el.classList.toggle('outside-scope',!!g&&el.dataset.group!==g.id);}for(const el of $('.world').querySelectorAll('[data-edge]')){const outside=!!g&&!linkInScope(el.dataset.edge);el.classList.toggle('outside-scope',outside);const label=el.classList.contains('edge-hit')?el.nextElementSibling:el.nextElementSibling?.nextElementSibling;if(label?.tagName.toLowerCase()==='text')label.classList.toggle('outside-scope',outside);}}

function answerReorderEditor(node,el){
 const clear=()=>el.querySelectorAll('[data-answer-row]').forEach(row=>row.classList.remove('drop-before','drop-after'));
 el.querySelectorAll('[data-answer-drag]').forEach(handle=>{
  handle.onpointerdown=e=>{
   if(e.button!==0)return;e.preventDefault();handle.setPointerCapture(e.pointerId);
   const from=+handle.dataset.answerDrag,startY=e.clientY;let insertion=null,moved=false;
   handle.onpointermove=event=>{if(Math.abs(event.clientY-startY)>4)moved=true;if(!moved)return;
    const pane=el.getBoundingClientRect();if(event.clientY<pane.top+35)el.scrollTop-=12;else if(event.clientY>pane.bottom-35)el.scrollTop+=12;
    const row=document.elementFromPoint(event.clientX,event.clientY)?.closest('[data-answer-row]');clear();insertion=null;if(!row||!el.contains(row))return;
    const after=event.clientY>row.getBoundingClientRect().top+row.offsetHeight/2;insertion=+row.dataset.answerRow+(after?1:0);row.classList.add(after?'drop-after':'drop-before');
   };
   const finish=event=>{handle.onpointermove=null;handle.onpointerup=null;handle.onpointercancel=null;clear();if(event.type==='pointerup'&&moved&&insertion!==null){const to=insertion-(from<insertion?1:0);if(to!==from)mutate(()=>reorderAnswer(node,from,to));}};
   handle.onpointerup=finish;handle.onpointercancel=finish;
  };
  handle.onkeydown=e=>{if(!e.altKey||!['ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const index=+handle.dataset.answerDrag,to=index+(e.key==='ArrowUp'?-1:1);if(to<0||to>=node.answers.length)return;mutate(()=>reorderAnswer(node,index,to));$('.right').querySelector('[data-answer-drag="'+to+'"]')?.focus();};
 });
}

function connectionSummary(){
 $('.connection-summary')?.remove();const link=linkObject();if(!link)return;
 const [type,index]=selectedLink.split(':'),source=flow.nodes.find(n=>n.id===(type==='r'?link.source:flow.nodes[+index]?.id)),target=flow.nodes.find(n=>n.id===link.target);if(!source||!target)return;
 const panel=document.createElement('section');panel.className='connection-summary';panel.setAttribute('aria-label','Connection summary');
 const card=(node,role)=>`<button type="button" class="summary-card" data-summary-node="${esc(node.id)}" title="Center canvas on ${esc(node.questionCode||node.id)}"><small>${role}</small><strong>${esc(node.questionCode||node.id)}</strong><span>${esc(node.title)}</span></button>`;
 panel.innerHTML=`<div class="summary-heading"><strong>Connection summary</strong><button type="button" class="summary-close" aria-label="Close connection summary">×</button></div>${card(source,'From')}<div class="summary-arrow"><span aria-hidden="true">↓</span><span>${esc(link.connectionLabel||link.displayLabel||link.visibilityLabel||link.label||'Connection')}</span></div>${card(target,'To')}`;
 $('.canvas').append(panel);panel.addEventListener('wheel',e=>e.stopPropagation());
 panel.querySelector('.summary-close').onclick=()=>{selectedLink=null;render();};
 panel.querySelectorAll('[data-summary-node]').forEach(button=>button.onclick=()=>{const node=flow.nodes.find(n=>n.id===button.dataset.summaryNode);if(!node)return;focusNodes([node],1);rememberFocus([node]);const card=$('.world').querySelector('[data-id="'+CSS.escape(node.id)+'"]');card?.classList.remove('summary-focus');requestAnimationFrame(()=>card?.classList.add('summary-focus'));});
}

function createConnection(sourceId,targetId,oldLink=null){
 const source=flow.nodes.find(n=>n.id===sourceId),target=flow.nodes.find(n=>n.id===targetId);if(!source||!target)return;if(source.type==='question'&&target.type==='shape'){toast('Choose a question or outcome as the destination.');return;}
 const discardOld=()=>{if(oldLink)flow.referenceLinks=flow.referenceLinks.filter(link=>link!==oldLink);};
 if(source.type!=='question'||(source.details?.responseType&&source.details.responseType!=='SINGLE_SELECT')){mutate(()=>{discardOld();selectedLink=createExecutableConnection(flow,sourceId,targetId);});toast(source.type==='question'?'Continuation connected; preview will follow it.':'Diagram connection added.');return;}
 modal(`<h3>Connect ${esc(source.questionCode||source.id)} → ${esc(target.questionCode||target.id)}</h3><p>Which answer should lead to this question?</p><div class="options">${source.answers.map((answer,index)=>`<button data-connect-answer="${index}">${esc(answer.label)}${answer.target?`<small>Currently goes to ${esc(answer.target)}</small>`:''}</button>`).join('')}</div><label>Or add an answer</label><input id="new-connection-answer" placeholder="Answer label"><button id="create-connection-answer">Add answer and connect</button>`);
 const finish=index=>{mutate(()=>{discardOld();selectedLink=createExecutableConnection(flow,sourceId,targetId,index);});$('.modal-backdrop')?.remove();toast('Answer connected; preview will follow it.');};
 document.querySelectorAll('[data-connect-answer]').forEach(button=>button.onclick=()=>finish(+button.dataset.connectAnswer));
 $('#create-connection-answer').onclick=()=>{const label=$('#new-connection-answer').value.trim();if(!label)return;mutate(()=>{discardOld();source.answers.push({label,value:label,target:'',sortOrder:source.answers.length+1});selectedLink=createExecutableConnection(flow,sourceId,targetId,source.answers.length-1);});$('.modal-backdrop')?.remove();};
}

function reviewRouting(){
 const audit=routingAudit(flow);
 const list=items=>items.length?'<ul>'+items.map(item=>'<li>'+esc(Object.entries(item).map(([key,value])=>key+': '+(Array.isArray(value)?value.join(' / '):value??'None')).join(' · '))+'</li>').join('')+'</ul>':'<p>None found.</p>';
 modal(`<h3>Questionnaire routing review</h3><p>Answer destinations and question continuations drive the preview. Inferred visibility lines are references; they do not create answer jumps.</p><h4>Manual lines needing an answer (${audit.unboundConnections.length})</h4>${list(audit.unboundConnections)}<h4>Continuation conflicts (${audit.continuationConflicts.length})</h4>${list(audit.continuationConflicts)}<h4>Unresolved visibility rules (${audit.unresolvedVisibility.length})</h4>${list(audit.unresolvedVisibility)}<h4>Answers using default order (${audit.answersUsingDefaultOrder.length})</h4><p>Default order may be intentional. Review any answer that should skip to a different question.</p>${list(audit.answersUsingDefaultOrder)}<button id="download-route-audit">Download routing review</button>`);
 $('#download-route-audit').onclick=()=>download(JSON.stringify(audit,null,2),'routing-review.json','application/json');
}

function reviewArchive(){const entries=flow.archivedQuestions||[];modal(`<h3>Archived questions (${entries.length})</h3>${flow.archiveRecovery?.unrecoverableIds?.length?`<p class="source-warning">Unable to recover these deleted IDs from available backups/source: ${esc(flow.archiveRecovery.unrecoverableIds.join(', '))}. Import a previous project JSON to recover their data.</p>`:''}<p>Archived questions stay in project JSON and do not appear in the active canvas or preview.</p>${entries.map(entry=>`<div class="section"><strong>${esc(entry.id)}</strong><p>${esc(entry.node.title)}</p><button data-restore-archive="${esc(entry.id)}">Restore question</button></div>`).join('')||'<p>No archived questions.</p>'}`);document.querySelectorAll('[data-restore-archive]').forEach(button=>button.onclick=()=>{if(!backupFlow())return;mutate(()=>restoreArchived(flow,button.dataset.restoreArchive));$('.modal-backdrop')?.remove();});}

function recoverAllDeleted(project){let backup=null,source=null;try{backup=JSON.parse(localStorage.getItem('question-tree-backup'));}catch{}try{if(project.sourcePackage)source=convertPackage(project.sourcePackage);}catch{}return recoverDeletedQuestions(project,[backup,source,suppliedFlow,sourceBaseline]).changed;}

function prepareSharedProject(data){const incoming=validate(structuredClone(data));correctQ075(incoming);correctManagement(incoming);correctRefinance(incoming);connectHelpRoute(incoming);correctWholesaleIntent(incoming);upgradeManualConnections(incoming);correctInsurance(incoming);correctMud(incoming);archiveQ011(incoming,suppliedFlow.archivedQuestions?.find(entry=>entry.id==='Q011'));recoverAllDeleted(incoming);correctExchange(incoming);correctFinancing(incoming);adoptSpouseName(incoming);correctHomestead(incoming);correctSpouseName(incoming);automaticSpouseSigning(incoming);correctMortgage(incoming);correctLoanStatus(incoming);correctMonthlyDebt(incoming);correctConfirmedRoutes(incoming);return upgradeForDeployment(incoming,suppliedFlow,sourceBaseline).flow;}
function startSharedSync(){
 let baseline=null;try{const saved=JSON.parse(localStorage.getItem('question-tree-team-baseline'));if(saved?.revision===cloudRevision)baseline=saved.flow;}catch{}
 autoSync=new SharedSync({revision:cloudRevision,dirty:cloudDirty,baseline,socketFactory:()=>new WebSocket(new URL('/api/project/live',location.href).href.replace(/^http/,'ws')),onBaseline:(data,revision)=>{try{localStorage.setItem('question-tree-team-baseline',JSON.stringify({revision,flow:data}));}catch{}},getFlow:()=>flow,isBusy:()=>!!drag,isEditing:()=>!!$('.modal-backdrop')||(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!!document.activeElement.closest('.right,header')),
  applyRemote:(data,{initial,merged})=>{const incoming=prepareSharedProject(data);const previous=flow,previousKey=selectedLink,previousLink=linkObject(),previousSource=previousKey?sourceIdForLink():null;const owners=new Set();for(const group of incoming.groups)for(const id of group.members){if(owners.has(id))throw Error('Concurrent edits assigned a card to multiple groups.');owners.add(id);}for(const link of incoming.referenceLinks||[])if(link.executable&&incoming.nodes.find(n=>n.id===link.source)?.continueTarget!==link.target)throw Error('Concurrent edits changed both a route and its destination.');try{localStorage.setItem('question-tree-cloud-backup',JSON.stringify(flow));}catch{throw Error('Could not save a local recovery copy; shared loading paused');}if(initial&&hadLocalProject&&cloudRevision===null){try{localStorage.setItem('question-tree-local-draft',JSON.stringify(flow));}catch{}}flow=incoming;const rebase=stack=>stack.flatMap(snapshot=>{const result=mergeProject(previous,JSON.parse(snapshot),incoming);if(result.conflicts.length)return [];try{validate(result.value);return [JSON.stringify(result.value)];}catch{return [];}});history=initial?[]:rebase(history);future=initial?[]:rebase(future);selected=new Set([...selected].filter(id=>incoming.nodes.some(n=>n.id===id)));selectedGroups=new Set([...selectedGroups].filter(id=>incoming.groups.some(g=>g.id===id)));selectedLink=null;if(previousLink){if(previousKey.startsWith('r:')){const index=incoming.referenceLinks?.findIndex(l=>(previousLink.id&&l.id===previousLink.id)||(l.source===previousSource&&l.target===previousLink.target&&l.kind===previousLink.kind));if(index>=0)selectedLink='r:'+index;}else{const index=incoming.nodes.findIndex(n=>n.id===previousSource),answer=index<0?-1:incoming.nodes[index].answers.findIndex(a=>a.value===previousLink.value&&a.label===previousLink.label);if(answer>=0)selectedLink='a:'+index+':'+answer;}}$('.title').value=flow.title;render();if(initial)initialFocus();},
  onState:state=>{cloudRevision=state.revision;cloudDirty=state.dirty;try{if(cloudRevision!==null)localStorage.setItem('question-tree-team-revision',String(cloudRevision));localStorage.setItem('question-tree-team-dirty',cloudDirty?'1':'0');}catch{}$('#status').textContent=state.message;$('#team').textContent=state.code==='conflict'?'Resolve conflict':'Team project';}
 });autoSync.start();
 window.addEventListener('online',()=>autoSync.refresh());window.addEventListener('focus',()=>autoSync.refresh());document.addEventListener('visibilitychange',()=>{if(document.hidden)autoSync.flush();else autoSync.refresh();});
 document.addEventListener('focusout',()=>{if(autoSync.pendingRemote||(!autoSync.ready&&!autoSync.blocked))setTimeout(()=>{autoSync.pendingRemote=null;autoSync.refresh();},100);});
 window.addEventListener('beforeunload',event=>{if(cloudDirty){event.preventDefault();event.returnValue='';}});
}
startSharedSync();

function reviewSyncConflicts(){
 const conflicts=autoSync.conflicts;const value=data=>data===undefined?'(deleted)':typeof data==='string'?data:JSON.stringify(data,null,2);
 modal(`<h3>Resolve shared edits</h3><p>${conflicts.some(conflict=>!conflict.path.length)?'This conflict affects workflow relationships. Compare both complete project versions before choosing one.':'Independent changes are preserved. Choose which value to keep for each field changed by both editors.'}</p>${conflicts.map((conflict,index)=>`<div class="section"><strong>${esc(conflict.pathName||'Project')}</strong>${conflict.message?`<p>${esc(conflict.message)}</p>`:''}<details><summary>Compare both versions</summary><p>Your value</p><pre class="source-json">${esc(value(conflict.local))}</pre><p>Team value</p><pre class="source-json">${esc(value(conflict.remote))}</pre></details><select data-conflict-choice="${index}" aria-label="Choose version for ${esc(conflict.pathName)}"><option value="">Choose…</option><option value="local">Keep my value</option><option value="remote">Keep team value</option></select></div>`).join('')}<button id="apply-sync-resolution">Save resolved changes</button>`);
 $('#apply-sync-resolution').onclick=async()=>{const choices={};document.querySelectorAll('[data-conflict-choice]').forEach(select=>choices[conflicts[+select.dataset.conflictChoice].pathName]=select.value);try{await autoSync.resolveConflicts(choices);if(!autoSync.blocked)$('.modal-backdrop')?.remove();else toast('A newer overlapping edit needs review.');}catch(error){toast(error.message);}};
}
